22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
45	const BASE_PREMIUM_RATES: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	};
53	
54	const CURSE_SURCHARGE_RATE = 0.5;
55	const HIGH_ENCHANTMENT_THRESHOLD = 5;
56	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
57	const LOYALTY_YEARS_THRESHOLD = 2;
58	const LOYALTY_DISCOUNT_RATE = 0.2;
59	const COMPONENT_BLOCK_SIZE = 3;
60	const COMPONENT_BLOCK_PREMIUM = 60;
61	
62	const countByType = (items: Item[]): Map<string, number> =>
63	  items.reduce(
64	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
65	    new Map<string, number>(),
66	  );
67	
68	const basePremiumForGroup = (type: string, itemCount: number): number =>
69	  itemCount === COMPONENT_BLOCK_SIZE
70	    ? COMPONENT_BLOCK_PREMIUM
71	    : itemCount * BASE_PREMIUM_RATES[type];
72	
73	// The policy base premium: the sum of all item base premiums, EXCLUDING
74	// item-specific surcharges. Policy-wide modifiers are percentages of this.
75	const policyBasePremium = (items: Item[]): number =>
76	  [...countByType(items)].reduce(
77	    (sum, [type, itemCount]) => sum + basePremiumForGroup(type, itemCount),
78	    0,
79	  );
80	
81	const itemSurchargeRate = (item: Item): number =>
82	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
83	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
84	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
85	    : 0);
86	
87	const sumItemSurcharges = (items: Item[]): number =>
88	  items.reduce(
89	    (sum, item) => sum + BASE_PREMIUM_RATES[item.type] * itemSurchargeRate(item),
90	    0,
91	  );
92	
93	// Premiums round in the MHPCO's favor, i.e. up.
94	const roundPremiumInMHPCOsFavor = (premium: number): number =>
95	  Math.ceil(premium);
96	
97	const quote = (items: Item[], customer: Customer): StepResult => {
98	  const basePremium = policyBasePremium(items);
99	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
100	  const loyaltyDiscount =
101	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
102	      ? basePremium * LOYALTY_DISCOUNT_RATE
103	      : 0;
104	
105	  return {
106	    premium: roundPremiumInMHPCOsFavor(
107	      basePremium +
108	        sumItemSurcharges(items) +
109	        firstInsuranceSurcharge -
110	        loyaltyDiscount +
111	        PROCESSING_FEE,
112	    ),
113	  };
114	};
115	
116	const runStep = (step: Step, customer: Customer): StepResult => {
117	  switch (step.op) {
118	    case "quote":
119	      return quote(step.items, customer);
120	    default:
121	      throw new Error(`Unsupported step: ${step.op}`);
122	  }
123	};
124	
125	export const runScenario = (scenario: Scenario): ScenarioResult => ({
126	  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
127	});
