// Each policy-wide modifier is a signed percentage of the policy base premium:
// surcharges positive, discounts negative. Each is multiplied out against the
// base premium SEPARATELY and then summed — summing the rates first and doing a
// single multiply is algebraically equal but not equal in floating point
// (100 * (1 + 0.1) === 110.00000000000001), and rounding up turns that into a
// spurious extra gold piece.
const policyWideModifierRates = (customer: Customer): number[] => [
  FIRST_INSURANCE_SURCHARGE_RATE,
  ...(customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
    ? [-LOYALTY_DISCOUNT_RATE]
    : []),
];

const sumPolicyWideModifiers = (
  basePremium: number,
  customer: Customer,
): number =>
  policyWideModifierRates(customer).reduce(
    (sum, rate) => sum + basePremium * rate,
    0,
  );

const quote = (items: Item[], customer: Customer): StepResult => {
  const basePremium = policyBasePremium(items);

  return {
    premium: roundPremiumInMHPCOsFavor(
      basePremium +
        sumItemSurcharges(items) +
        sumPolicyWideModifiers(basePremium, customer) +
        PROCESSING_FEE,
    ),
  };
};

